from treasure_hunt import SYMBOLS

def render(page):
    icons='<template data-memory-symbol="Unicorn"><span class="unicorn-face" aria-hidden="true">🦄</span></template>'
    icons+=''.join(f'<template data-memory-symbol="{name}"><svg viewBox="0 0 100 100" aria-hidden="true" focusable="false">{shape}</svg></template>' for name,shape in SYMBOLS[:5])
    body='''<main id="main"><div class="page-intro"><div class="wrap"><div class="breadcrumbs"><a href="/">Home</a> / <a href="/tools/unicorn-party-games.html">Games</a></div><span class="eyebrow">Free browser game</span><h1>Unicorn memory game</h1><p>Find six magical pairs! Tap two cards to reveal their pictures. Match them all and try to beat your number of moves.</p></div></div><div class="article wrap memory-page"><section aria-labelledby="memory-heading"><h2 id="memory-heading">Find the matching pairs</h2><p>No timer. Play at your own pace, alone or taking turns with a friend. Use Tab to move between cards and Enter or Space to turn one over.</p><div class="memory-toolbar"><p><strong>Moves: <span id="memory-moves">0</span></strong> · Pairs: <span id="memory-pairs">0</span> / 6</p><button class="button" id="memory-reset" type="button" hidden>New game</button></div><p id="memory-status" role="status" aria-live="polite" aria-atomic="true">Loading your cards…</p><noscript><p>Enable JavaScript to play, or try our <a href="/tools/unicorn-treasure-hunt.html">printable treasure hunt</a>.</p></noscript><div id="memory-board" class="memory-board" role="group" aria-label="Memory cards"></div><button class="button button-light" id="memory-continue" type="button" hidden>Turn these cards back</button>'''+icons+'''</section><section class="callout"><h2>How to play</h2><ol><li>Turn over any two different cards. That counts as one move.</li><li>If the pictures match, they stay face up.</li><li>If they do not match, study them, then choose “Turn these cards back” when you are ready.</li><li>Find all six pairs to finish. “New game” shuffles the cards and resets your moves.</li></ol><p>The game does not save your score, ask for a name or send your moves to us. Reloading starts a fresh game.</p></section><section><h2>More unicorn fun</h2><p><a href="/tools/unicorn-treasure-hunt.html">Print a unicorn treasure hunt</a> for an away-from-screen activity, or <a href="/tools/unicorn-party-games.html#bingo">make bingo cards</a> for your party.</p><p>Organising a birthday? Our <a href="/tools/unicorn-party-planner.html">party planner</a> helps with supplies and a budget, and the <a href="/tools/birthday-cake-servings-calculator.html">cake guide</a> has decorating ideas.</p></section></div><script src="/assets/memory-game.js" defer></script></main>'''
    return page('Free Unicorn Memory Game — Play Online | Unicorn Finds','Play a free unicorn memory matching game in your browser. Find six pairs at your own pace on mobile or desktop. No account or download required.','/tools/unicorn-memory-game.html',body).replace('</head>','<link rel="stylesheet" href="/assets/memory-game.css"></head>')
